)) * 2 / w end\n\tend\n\t-- first slide up (as far as the top allows), then shrink if it still doesn't fit\n\tlocal function fitTo(lb)\n\t\tlocal over = top + h - lb\n\t\tlocal shift = 0\n\t\tif over > 0 then shift = math.min(over, math.max(0, top - limitTop)) end\n\t\tlocal centre = top - shift + h / 2\n\t\treturn math.min(1, (lb - centre) * 2 / h, (centre - limitTop) * 2 / h), shift\n\tend\n\tlocal k, shift = fitTo(limitBottom)\n\tif kSide and kSide > k then\n\t\tlocal k2, shift2 = fitTo(screenBottom)\n\t\tk2 = math.min(k2, kSide)\n\t\tif k2 > k then k, shift = k2, shift2 end\n\tend\n\twin.Position = basePos - UDim2.fromOffset(0, shift)\n\treturn math.max(k, 0.5)\nend", 806413669, 955374160},
